from qgis.core import QgsRasterLayer, QgsProject
import traceback

name = "ESRI World Imagery"
proj = QgsProject.instance()
try:
    existing = proj.mapLayersByName(name)
    if existing:
        out = {"status": "exists", "id": existing[0].id()}
    else:
        url = "type=xyz&url=https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}"
        layer = QgsRasterLayer(url, name, "wms")
        ok = proj.addMapLayer(layer)
        out = {"status": "added", "ok": ok, "id": layer.id(), "total": len(proj.mapLayers())}
    print(out)
except Exception as e:
    print({"status": "error", "msg": str(e), "tb": traceback.format_exc()})

from qgis.core import QgsProject
