def describe(node, depth=0):
    from qgis.core import QgsLayerTreeGroup, QgsLayerTreeLayer
    if isinstance(node, QgsLayerTreeGroup):
        info = {"type": "group", "name": node.name(), "depth": depth}
        print(info)
        for c in node.children():
            describe(c, depth + 1)
    elif isinstance(node, QgsLayerTreeLayer):
        l = node.layer()
        print({"type": "layer", "name": l.name(), "visible": node.isVisible(), "depth": depth})

describe(root)
print({"total_map_layers": len(proj.mapLayers())})

from qgis.core import QgsProject, QgsLayerTreeGroup, QgsLayerTreeLayer

proj = QgsProject.instance()
root = proj.layerTreeRoot()
children = root.children()
out = []
for i, c in enumerate(children):
    if isinstance(c, QgsLayerTreeLayer):
        out.append({"index": i, "layer": c.layer().name()})
    elif isinstance(c, QgsLayerTreeGroup):
        out.append({"index": i, "group": c.name()})
    else:
        out.append({"index": i, "other": str(type(c))})
print(out)

from qgis.core import QgsProject, QgsLayerTreeGroup, QgsLayerTreeLayer

proj = QgsProject.instance()
root = proj.layerTreeRoot()
children = root.children()
out = []
for i, c in enumerate(children):
    try:
        if isinstance(c, QgsLayerTreeLayer):
            l = c.layer()
            out.append({"index": i, "kind": "layer", "layer": l.name() if l else None})
        elif isinstance(c, QgsLayerTreeGroup):
            out.append({"index": i, "kind": "group", "name": c.name()})
        else:
            out.append({"index": i, "kind": "other", "type": str(type(c))})
    except Exception as e:
        out.append({"index": i, "kind": "error", "msg": str(e)})
print(out)

