from qgis.core import QgsProject, QgsLayerTreeLayer, QgsLayerTreeGroup
proj = QgsProject.instance()
root = proj.layerTreeRoot()
valid_ids = set(proj.mapLayers().keys())
removed = 0
errors = 0
children = list(root.children())
for c in children:
    try:
        if isinstance(c, QgsLayerTreeLayer):
            l = c.layer()
            if l is None or l.id() not in valid_ids:
                root.removeChildNode(c)
                removed += 1
        elif isinstance(c, QgsLayerTreeGroup):
            if len(c.children()) == 0:
                root.removeChildNode(c)
                removed += 1
    except Exception:
        errors += 1
print({"removed": removed, "errors": errors, "children_left": len(root.children())})
